const pipeline = (x) => x();

const importers = [
  async (path) => {
  if (!/^\.[\\/](?:src(?:\/(?!\.)(?:(?:(?!(?:^|\/)\.).)*?)\/|\/|$)(?!\.)(?=.)[^/]*?\.stories\.tsx)$/.exec(path)) {
    return;
  }

  const pathRemainder = path.substring(6);
  return import(
    /* webpackChunkName: "[request]" */
    /* webpackInclude: /(?!.*node_modules)(?:\/src(?:\/(?!\.)(?:(?:(?!(?:^|\/)\.).)*?)\/|\/|$)(?!\.)(?=.)[^/]*?\.stories\.tsx)$/ */
    './src/' + pathRemainder
  );
}
,
async (path) => {
  if (!/^\.[\\/](?:src(?:\/(?!\.)(?:(?:(?!(?:^|\/)\.).)*?)\/|\/|$)(?!\.)(?=.)[^/]*?\.docs\.mdx)$/.exec(path)) {
    return;
  }

  const pathRemainder = path.substring(6);
  return import(
    /* webpackChunkName: "[request]" */
    /* webpackInclude: /(?!.*node_modules)(?:\/src(?:\/(?!\.)(?:(?:(?!(?:^|\/)\.).)*?)\/|\/|$)(?!\.)(?=.)[^/]*?\.docs\.mdx)$/ */
    './src/' + pathRemainder
  );
}

];

export async function importFn(path) {
  for (let i = 0; i < importers.length; i++) {
    const moduleExports = await pipeline(() => importers[i](path));
    if (moduleExports) {
      return moduleExports;
    }
  }
}