import type { PropsWithChildren } from 'react'
import React, { useEffect } from 'react'
import { IntlProvider } from 'react-intl'
import { useLocale } from '../../contexts/LocaleContext'
import { UiProvider } from '../../contexts/UiContext'
import type { AvailableLocales } from '../../locales'
import { en, es, fr, ko, pl, pt, ru, zh } from '../../locales'

const messages = { en, es, fr, ko, pl, pt, ru, zh }

export function TestingLocaleProvider({
  children,
  locale: localeOverride,
}: PropsWithChildren<Record<string, unknown>>): JSX.Element {
  const [locale, setLocale] = useLocale()

  useEffect(() => {
    if (localeOverride && locale !== localeOverride) {
      setLocale(localeOverride as keyof AvailableLocales)
    }
  }, [locale, localeOverride, setLocale])

  return (
    <IntlProvider locale={locale} messages={messages[locale]}>
      {children}
    </IntlProvider>
  )
}

export function TestingUiProvider({
  locale,
  children,
}: PropsWithChildren<Record<string, unknown>>): JSX.Element {
  return (
    <UiProvider>
      <TestingLocaleProvider locale={locale}>{children}</TestingLocaleProvider>
    </UiProvider>
  )
}
